    # return list of (start,end) segments after merge
    segments=[]
    start=0
    for m in re.finditer(r'[，,;；。\n]+|\s+/\s+', text):
        end=m.start()
        if end>start:
            segments.append((start,end))
        start=m.end()
    if start<len(text):
        segments.append((start,len(text)))
    merged=[]
    for st,ed in segments:
        seg=text[st:ed].strip()
        if not seg:
            continue
        if is_noise(seg):
